<!doctype html>
<html lang="{{ str_replace('_', '-', app()->getLocale()) }}">
<head>
  <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Print Card (Back) - {{ $application->reference }}</title>
  <style>
    *{box-sizing:border-box}@page{size:86mm 54mm;margin:0}html,body{height:100%;margin:0}body{display:flex;align-items:center;justify-content:center;background:#fff;font-family:Arial,Helvetica,sans-serif;overflow:hidden;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}.card{position:relative;width:86mm;height:54mm;overflow:hidden;background:#f8fafc;border:.6mm solid #172554;border-radius:3mm;color:#172554;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}.band{height:11mm;padding:2.2mm 4mm;display:flex;align-items:center;justify-content:space-between;background:#000;color:#fff;border-bottom:.8mm solid #d6a900}.band strong{font-size:2.8mm;line-height:1.05}.band .media{color:#f7d46a}.band>span{max-width:45%;text-align:right;color:#f7d46a;font-size:1.5mm;line-height:1.15;font-weight:800}.main{display:flex;gap:2.5mm;align-items:flex-start;margin:2mm 4mm 0;overflow:hidden}.copy{flex:1;min-width:0}.contact{color:#1e293b;font-size:1.8mm;line-height:1.22}.contact strong{display:block;color:#172554;font-size:2.2mm;line-height:1.05;margin-bottom:.7mm}.contact strong .media{color:#1f6f43}.contact .tagline{color:#64748b;font-size:1.5mm;font-weight:700;margin-bottom:.7mm}.salutation{margin-top:1.7mm;color:#172554;font-size:2mm;font-weight:900}.body-text{margin-top:.6mm;color:#475569;font-size:1.7mm;line-height:1.25}.qr-panel{flex:0 0 22.5mm;width:22.5mm;padding:1mm .8mm .7mm;text-align:center;background:#fff;border:.3mm solid #d6a900;border-radius:1.7mm;box-shadow:0 .4mm 1.5mm rgba(15,23,42,.16)}#cardBackQr{width:19mm;height:19mm;margin:0 auto .5mm;display:flex;align-items:center;justify-content:center}#cardBackQr img,#cardBackQr canvas{display:block;max-width:100%;max-height:100%}.qr-label{color:#172554;font-size:1.5mm;font-weight:900;white-space:nowrap}.footer{position:absolute;left:0;right:0;bottom:1mm;text-align:center;color:#172554;font-size:1.6mm;font-weight:800}
  </style>
</head>
<body><div class="card"><div class="band"><strong>ZIMBABWE <span class="media">MEDIA</span> COMMISSION</strong><span>ZMC - promoting ethical and professional conduct by all media practitioner</span></div><div class="main"><div class="copy"><div class="contact"><strong>ZIMBABWE <span class="media">MEDIA</span> COMMISSION</strong><div class="tagline">Ethical and professional media practice</div><div>{{ config('organization.registered_address') }}</div><div>Tel: {{ config('organization.public_phone') }}</div><div>Fax: 253639</div><div>info@zmc.org.zw</div></div><div class="salutation">To Whom it May Concern</div><div class="body-text">This card confirms that the holder is accredited by the Zimbabwe Media Commission for the validity period shown on the front. Scan the QR code to verify its authenticity. Please accord him/her every assistance in the discharge of his/her duties.</div></div><div class="qr-panel"><div id="cardBackQr"></div><div class="qr-label">SCAN TO VERIFY</div></div></div><div class="footer">https://zmc.org.zw &nbsp; | &nbsp; Keep this card secure</div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>const issuanceUrl=@json(route('staff.production.issuance'));window.addEventListener('afterprint',()=>window.location.assign(issuanceUrl));window.addEventListener('load',()=>{const value=@json($payload['qr_value']??'');if(value&&window.QRCode)new QRCode(document.getElementById('cardBackQr'),{text:value,width:80,height:80,correctLevel:QRCode.CorrectLevel.M});setTimeout(()=>window.print(),350)});</script></body></html>
